package dev.eugheist.tc4modern;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.*;
import thaumcraft.api.nodes.NodeType;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class NodeWorldAudit {
 static final BlockPos BASE=new BlockPos(940,121,-90);static int ticks;static volatile String failed;static BrainyZombie normal,giant;static AuraNodeEntity hungry;static net.minecraft.world.entity.animal.Pig pig;
 static void check(boolean v,String message){if(!v)failed=message;System.out.println("TC4_NODE_WORLD "+(v?"PASS ":"FAIL ")+message);}
 static AuraNodeEntity node(net.minecraft.server.level.ServerLevel l,BlockPos p,NodeType type){l.setBlock(p,TC4Modern.AURA_NODE.get().defaultBlockState(),3);var n=(AuraNodeEntity)l.getBlockEntity(p);n.nodeType=type;n.reservoir.setAspects(new AspectList().add(Aspect.AIR,40));return n;}
 static void setup(net.minecraft.server.level.ServerPlayer p){var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);l.setDayTime(18000);l.updateSkyBrightness();p.getAbilities().flying=true;p.onUpdateAbilities();p.server.setDifficulty(net.minecraft.world.Difficulty.NORMAL,true);for(var e:l.getEntitiesOfClass(Entity.class,new AABB(BASE).inflate(45)))if(!(e instanceof net.minecraft.world.entity.player.Player))e.discard();for(int x=-16;x<=16;x++)for(int z=-16;z<=16;z++)for(int y=-1;y<7;y++)l.setBlock(BASE.offset(x,y,z),(y==-1?Blocks.SMOOTH_STONE:Blocks.AIR).defaultBlockState(),3);
 normal=BrainyContent.NORMAL.get().create(l);normal.moveTo(BASE.getX()-3,BASE.getY(),BASE.getZ()+5,180,0);normal.getAttribute(Champions.MOD).setBaseValue(-1);normal.setNoAi(true);normal.setYBodyRot(180);normal.setYHeadRot(180);l.addFreshEntity(normal);giant=BrainyContent.GIANT.get().create(l);giant.moveTo(BASE.getX(),BASE.getY(),BASE.getZ()+5,180,0);giant.getAttribute(Champions.MOD).setBaseValue(-1);giant.setNoAi(true);giant.setYBodyRot(180);giant.setYHeadRot(180);l.addFreshEntity(giant);check(normal.getMaxHealth()==25&&giant.getMaxHealth()==60&&normal.getArmorValue()==5,"original zombie health and armour");check(Math.abs(giant.getBbWidth()-1.32)<.001&&Math.abs(giant.getBbHeight()-3.96)<.001,"original giant initial collision size");for(int i=0;i<12;i++)giant.hurt(l.damageSources().generic(),.01f);check(giant.anger()==2,"giant gains anger even on rejected damage, capped at two");giant.aiStep();check(Math.abs(giant.anger()-1.998)<.0001&&Math.abs(giant.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE)-11.99)<.001,"anger decays and changes attack damage");
 var tainted=node(l,BASE.offset(12,2,0),NodeType.TAINTED);tainted.reservoir.count=50;NodeWorldEffects.tick(tainted);check(l.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.BIOME).getHolder(NodeWorldEffects.EERIE).isPresent(),"eerie biome registered with original monster list");
 var pure=node(l,BASE.offset(-12,2,0),NodeType.PURE);for(int x=-8;x<=8;x+=4)for(int z=-8;z<=8;z+=4)TaintBiomes.spread(l,pure.getBlockPos().offset(x,0,z));pure.reservoir.count=50;for(int i=0;i<120;i++)NodeWorldEffects.tick(pure);check(l.getBiome(pure.getBlockPos()).is(NodeWorldEffects.FOREST),"pure node converts tainted biome to magical forest");l.removeBlock(pure.getBlockPos(),false);l.removeBlock(tainted.getBlockPos(),false);
 var unstable=node(l,BASE.offset(10,3,10),NodeType.UNSTABLE);unstable.reservoir.count=100;for(int i=0;i<10;i++)NodeWorldEffects.tick(unstable);check(unstable.reservoir.aspects.getAmount(Aspect.AIR)<40&&!l.getEntitiesOfClass(AspectOrb.class,new AABB(unstable.getBlockPos()).inflate(2)).isEmpty(),"unstable node expels actual primal vis orbs");l.removeBlock(unstable.getBlockPos(),false);
 hungry=node(l,BASE.offset(8,3,0),NodeType.HUNGRY);pig=EntityType.PIG.create(l);pig.moveTo(hungry.getBlockPos().getX()+5,hungry.getBlockPos().getY()+.5,hungry.getBlockPos().getZ()+.5,0,0);pig.setNoAi(true);l.addFreshEntity(pig);NodeWorldEffects.tick(hungry);check(pig.getDeltaMovement().x<0,"hungry node pulls nearby creatures");pig.moveTo(hungry.getBlockPos().getX()+.5,hungry.getBlockPos().getY()+.5,hungry.getBlockPos().getZ()+.5,0,0);pig.setHealth(1);hungry.reservoir.setAspects(new AspectList());int baseVis=hungry.reservoir.aspectsBase.visSize();NodeWorldEffects.tick(hungry);check(!pig.isAlive()&&hungry.reservoir.aspectsBase.visSize()==baseVis+1,"hungry node consumes a creature and grows primal capacity: health="+pig.getHealth()+" base="+hungry.reservoir.aspectsBase.visSize()+" before="+baseVis+" aspects="+ScanTarget.entity(pig).aspects());pig.discard();for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)if(x!=0||y!=0||z!=0)l.setBlock(hungry.getBlockPos().offset(x,y,z),Blocks.STONE.defaultBlockState(),3);hungry.reservoir.count=50;for(int i=0;i<20;i++)NodeWorldEffects.tick(hungry);check(!l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(hungry.getBlockPos()).inflate(4),e->e.getItem().is(net.minecraft.world.item.Items.COBBLESTONE)).isEmpty(),"hungry node breaks ray-traced blocks and preserves their drops");var saved=hungry.saveWithoutMetadata(l.registryAccess());var copy=new AuraNodeEntity(hungry.getBlockPos(),hungry.getBlockState());copy.loadWithComponents(saved,l.registryAccess());check(copy.nodeType==NodeType.HUNGRY&&copy.reservoir.aspectsBase.visSize()==hungry.reservoir.aspectsBase.visSize(),"node type and consumed capacity persist");l.removeBlock(hungry.getBlockPos(),false);
 var dark=node(l,BASE.offset(0,0,12),NodeType.DARK);dark.reservoir.count=50;for(int i=0;i<2000;i++)NodeWorldEffects.tick(dark);check(l.getEntitiesOfClass(BrainyZombie.class,new AABB(dark.getBlockPos()).inflate(10,6,10),BrainyZombie::giant).size()==4,"dark node spawns original cap of four giant zombies: "+l.getEntitiesOfClass(BrainyZombie.class,new AABB(dark.getBlockPos()).inflate(10,6,10),BrainyZombie::giant).size());l.removeBlock(dark.getBlockPos(),false);l.getEntitiesOfClass(BrainyZombie.class,new AABB(dark.getBlockPos()).inflate(10,6,10),e->e.giant()&&e!=giant).forEach(Entity::discard);
 var nether=p.server.getLevel(net.minecraft.world.level.Level.NETHER);var generated=new BlockPos(0,5,0);for(int y=5;y<20;y++)nether.setBlock(generated.atY(y),(y<10?Blocks.NETHERRACK:Blocks.AIR).defaultBlockState(),3);boolean placed=new AuraNodeFeature().place(net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration.INSTANCE,nether,nether.getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(731),generated);boolean found=false;for(int y=10;y<=13;y++){var at=generated.atY(y);if(nether.getBlockEntity(at) instanceof AuraNodeEntity n){found=n.reservoir.aspects.visSize()>0;nether.removeBlock(at,false);}}check(placed&&found,"Nether wild node generates over first cave floor with actual aspects");
 for(int x=-4;x<=1;x++)l.setBlock(BASE.offset(x,-1,4),Blocks.GLOWSTONE.defaultBlockState(),3);
 p.getInventory().clearContent();p.containerMenu.broadcastChanges();p.connection.teleport(BASE.getX()-1,BASE.getY()+1,BASE.getZ()-5,0,0);
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.nodeWorldAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null)return;ticks++;var s=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==100)s.execute(()->{try{setup(s.getPlayerList().getPlayer(id));}catch(Throwable ex){failed=ex.toString();ex.printStackTrace();}});if(ticks==180)LiquidDeathAudit.shot(mc,"brainy-zombies.png");if(ticks==220){System.out.println(failed==null?"TC4_NODE_WORLD ALL PASS":"TC4_NODE_WORLD FAILED "+failed);mc.stop();}}
}
